# заканчивается ошибкой «недостаточно прав».
APPEND_ONLY_SQL = """
CREATE FUNCTION integrations_exchange_append_only() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'Журнал обмена только пополняется: операция % запрещена', TG_OP
        USING ERRCODE = 'insufficient_privilege';
END
$$;

CREATE TRIGGER integrations_exchange_no_update_delete
    BEFORE UPDATE OR DELETE ON integrations_exchange
    FOR EACH ROW EXECUTE FUNCTION integrations_exchange_append_only();

CREATE TRIGGER integrations_exchange_no_truncate
    BEFORE TRUNCATE ON integrations_exchange
    FOR EACH STATEMENT EXECUTE FUNCTION integrations_exchange_append_only();
"""

